package br.com.archlab.api;
import br.com.archlab.api.v3.*;import br.com.archlab.simulation.core.v3.*;import tools.jackson.databind.json.JsonMapper;import org.junit.jupiter.api.Test;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class SimulationResultV3Test {
    private final JsonMapper json=JsonMapper.builder().build();
    SimulationRequestV3 request() throws Exception {var input=json.readTree(Files.readString(Path.of("../../docs/examples/v3/ce-ref-01-request.json")));return new SimulationRequestV3(new ArchitectureRequestMapperV3().architecture(input.get("architecture")),new SimulationRequestV3.Scenario(new IdentifierV3("ce-ref-01"),new SimulationRequestV3.Entry(new IdentifierV3("client"),new IdentifierV3("api-op"),new IdentifierV3("client-api"),null),List.of(),Map.of()),new SimulationRequestV3.Options(7,SimulationRequestV3.CompletionMode.DRAIN_ALL,null));}
    Map<String,Object> execute(SimulationRequestV3 req,String file) throws Exception {var engine=new SimulationEngineV3(req);engine.run();var result=new SimulationResponseMapperV3().map(ResultProjectorV3.project(engine.checkpoint()));Files.createDirectories(Path.of("target/v3-results"));Files.writeString(Path.of("target/v3-results/"+file+".json"),json.writeValueAsString(result));return result;}
    @Test void referenceAndHorizonProduceCanonicalContractArtifacts() throws Exception {var req=request();var result=execute(req,"ce-ref-01");var tree=json.valueToTree(result);assertEquals(120,tree.at("/principal/responseDurationMs").longValue());assertEquals(210,tree.at("/global/completionDurationMs").longValue());assertTrue(tree.at("/integrity/publicSnapshotReconstructible").booleanValue());assertFalse(tree.at("/integrity/playbackReconstructible").booleanValue());var copy=new TreeMap<>(result);var integrity=(Map<?,?>)copy.remove("integrity");assertEquals(integrity.get("normalizedResultDigest"),new SimulationResponseMapperV3().digest(copy));assertEquals(result,execute(req,"ce-ref-01-repeat"));var partial=execute(new SimulationRequestV3(req.architecture(),req.scenario(),new SimulationRequestV3.Options(7,SimulationRequestV3.CompletionMode.UNTIL_HORIZON,150L)),"horizon-150");assertEquals("HORIZON_REACHED",json.valueToTree(partial).at("/global/status").asText());}
}
